def augment(residual, s, t):
    path = find_path(residual, s, t)   # any s-t path w/ residual > 0
    if not path:
        return 0
    bottleneck = min(residual[u][v] for u, v in path)
    for u, v in path:
        residual[u][v] -= bottleneck
        residual[v][u] += bottleneck    # backward edge
    return bottleneck

