            d = dfs(v, min(pushed, cap[u][v]), level, it, cap, t)
            if d:
                cap[u][v] -= d
                cap[v][u] += d
                return d
        it[u] += 1   # skip dead edge for the rest of this phase
    return 0

def min_cut(residual, s):
    seen, stack = {s}, [s]
    while stack:
        u = stack.pop()
        for v in residual[u]:
            if residual[u][v] > 0 and v not in seen:
                seen.add(v); stack.append(v)
    # cut edges: original u->v with u in seen, v not in seen
    return seen

