def convex_hull(pts):
    pts = sorted(set(pts))
    if len(pts) <= 2:
        return pts
    def half(points):
        h = []
        for p in points:
            while len(h) >= 2 and cross(h[-2], h[-1], p) <= 0:
                h.pop()
            h.append(p)
        return h
    lower = half(pts)
    upper = half(reversed(pts))
    return lower[:-1] + upper[:-1]

def point_in_polygon(pt, poly):
    x, y = pt; inside = False; n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]; xj, yj = poly[j]
        if (yi > y) != (yj > y):
            xint = (xj - xi) * (y - yi) / (yj - yi) + xi
            if x < xint:
                inside = not inside
        j = i
    return inside

from collections import OrderedDict

class LRUCache:
    def __init__(self, cap):
        self.cap = cap
        self.d = OrderedDict()
    def get(self, key):
        if key not in self.d:
            return -1
        self.d.move_to_end(key)
        return self.d[key]
    def put(self, key, val):
        if key in self.d:
            self.d.move_to_end(key)
        self.d[key] = val
        if len(self.d) > self.cap:
            self.d.popitem(last=False)  # evict LRU

class LFUCache:
    def __init__(self, cap):
        self.cap = cap
        self.key_to = {}          # key -> (val, freq)
        self.freq_to = {}         # freq -> ordered keys
        self.min_freq = 0
    def _bump(self, key):
        val, f = self.key_to[key]
        self.freq_to[f].pop(key)
        if not self.freq_to[f] and f == self.min_freq:
            self.min_freq += 1
        self.key_to[key] = (val, f+1)
        self.freq_to.setdefault(f+1, OrderedDict())[key] = None

