class BloomFilter:
    def __init__(self, m, k):
        self.m, self.k = m, k
        self.bits = bytearray(m // 8 + 1)
    def _idx(self, item, i):
        return (mmh3.hash(item, i) % self.m)
    def add(self, item):
        for i in range(self.k):
            b = self._idx(item, i)
            self.bits[b >> 3] |= (1 << (b & 7))
    def __contains__(self, item):
        return all(self.bits[(b := self._idx(item, i)) >> 3] & (1 << (b & 7))
                   for i in range(self.k))

