def rabin_karp(text, pat, B=256, MOD=1_000_000_007):
    n, m = len(text), len(pat)
    if m > n: return []
    hp = ht = 0
    high = pow(B, m-1, MOD)
    for i in range(m):
        hp = (hp*B + ord(pat[i])) % MOD
        ht = (ht*B + ord(text[i])) % MOD
    res = []
    for i in range(n - m + 1):
        if hp == ht and text[i:i+m] == pat:
            res.append(i)
        if i < n - m:
            ht = ((ht - ord(text[i])*high)*B + ord(text[i+m])) % MOD
    return res

