def sieve(n):
    is_prime = bytearray([1]) * (n+1)
    is_prime[0] = is_prime[1] = 0
    p = 2
    while p*p <= n:
        if is_prime[p]:
            for m in range(p*p, n+1, p):
                is_prime[m] = 0
        p += 1
    return [i for i in range(2, n+1) if is_prime[i]]

def mod_pow(base, exp, m):
    result = 1
    base %= m
    while exp > 0:
        if exp & 1:
            result = (result * base) % m
        base = (base * base) % m
        exp >>= 1
    return result

def mat_mul(A, B, mod):
    n = len(A)
    return [[sum(A[i][k]*B[k][j] for k in range(n)) % mod
             for j in range(n)] for i in range(n)]

def mat_pow(M, p, mod):
    n = len(M)
    R = [[int(i==j) for j in range(n)] for i in range(n)]  # identity
    while p:
        if p & 1:
            R = mat_mul(R, M, mod)
        M = mat_mul(M, M, mod)
        p >>= 1
    return R

from bisect import bisect_left

def subset_sum(nums, target):
    n = len(nums); half = n // 2
    def sums(arr):
        out = [0]
        for x in arr:
            out += [s + x for s in out]
        return out
    left = sorted(sums(nums[:half]))
    for s in sums(nums[half:]):
        need = target - s
        i = bisect_left(left, need)
        if i < len(left) and left[i] == need:
            return True
    return False

