import heapq

def k_way_merge(run_iters):
    heap = []
    for idx, it in enumerate(run_iters):
        first = next(it, None)
        if first is not None:
            heapq.heappush(heap, (first, idx))
    while heap:
        val, idx = heapq.heappop(heap)
        yield val
        nxt = next(run_iters[idx], None)
        if nxt is not None:
            heapq.heappush(heap, (nxt, idx))

