def contract(edges, n):
    parent = list(range(n))
    def find(x):
        while parent[x] != x: x = parent[x]
        return x
    count = n
    while count > 2:
        u, v = random.choice(edges)
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
            count -= 1
    return sum(1 for u, v in edges if find(u) != find(v))

